descriptor.controllerScript:
self.onInit = function() {
    utils = self.ctx.$scope.$injector.get(self.ctx.servicesMap.get('utils'));
    settings = utils.deepClone(self.ctx.settings) || {};

    self.ctx.$scope.type = settings.type;
    self.ctx.$scope.datasource = [];
    self.ctx.$scope.displayedColumns = [];
    self.ctx.$scope.noData = false;

    if(settings.type == "Device thresholds"){
        self.ctx.$scope.datasource = [];

        self.ctx.$scope.displayedColumnsTable = [
            {key: "type", label: "Type", isAction: false}, 
            {key: "upperThreshold", label: "Upper Threshold", isAction: false}, 
            {key: "lowerThreshold", label: "Lower Threshold", isAction: false}, 
            {key: "equalThreshold", label: "Equal Threshold", isAction: false}, 
            {key: "durationThreshold", label: "Duration Threshold", isAction: false}, 
            {key: "status", label: "Status", isAction: false}, 
            {key: "edit", label: "Edit", isAction: true, actionKey: "edit"}
        ];

        self.ctx.$scope.displayedColumns = ["type", "upperThreshold", "lowerThreshold", "equalThreshold", "durationThreshold", "status", "edit"];
    } else {
        self.ctx.$scope.datasource = [];

        self.ctx.$scope.displayedColumnsTable = [
            {key: "eventType", label: "Event Type", isAction: false}, 
            {key: "duration", label: "Duration", isAction: false}, 
            {key: "edit", label: "Edit", isAction: true, actionKey: "edit"},
            {key: "delete_outline", label: "Delete", isAction: true, actionKey: "delete_outline"}
        ];

        self.ctx.$scope.displayedColumns = ["eventType", "duration", "edit", "delete"];
    }

    self.ctx.$scope.edit = function(element){
        let actionEventDescriptors = self.ctx.$scope.ctx.actionsApi.getActionDescriptors('elementClick');
        let actionEvent;

        if (actionEventDescriptors.length) {	
            actionEventDescriptors.forEach(action=>{
                if(action.name == 'edit'){
                    actionEvent = action;
                }
            });

            setTimeout(() => {
                self.ctx.$scope.ctx.actionsApi.handleWidgetAction(null, actionEvent, null, null, element);	
            }, 0);	
        }
    };

    self.ctx.$scope.delete = function(element){
        let actionEventDescriptors = self.ctx.$scope.ctx.actionsApi.getActionDescriptors('elementClick');
        let actionEvent;

        if (actionEventDescriptors.length) {	
            actionEventDescriptors.forEach(action=>{
                if(action.name == 'delete'){
                    actionEvent = action;
                }
            });

            setTimeout(() => {
                self.ctx.$scope.ctx.actionsApi.handleWidgetAction(null, actionEvent, null, null, element);	
            }, 0);	
        }
    };
};

self.onDataUpdated = function() {
    self.ctx.$scope.datasource = [];

    if(self.ctx.data[0].data[0]){
        if(self.ctx.data[0].data[0][1] && JSON.parse(self.ctx.data[0].data[0][1])){
            self.ctx.$scope.alarmConfig = JSON.parse(self.ctx.data[0].data[0][1]);
            if(self.ctx.$scope.type == "Device thresholds"){
                if(self.ctx.$scope.alarmConfig.deviceThresholds){
                    self.ctx.$scope.datasource = self.ctx.$scope.alarmConfig.deviceThresholds;
                } else {
                    self.ctx.$scope.alarmConfig.deviceThresholds = [];

                    self.ctx.$scope.alarmConfig.deviceThresholds.push({
                        type: "Temperature",
                        status: false,
                        upperThreshold: null,
                        lowerThreshold: null,
                        equalThreshold: null,
                    });
                    self.ctx.$scope.alarmConfig.deviceThresholds.push({
                        type: "Battery level",
                        status: false,
                        upperThreshold: null,
                        lowerThreshold: null,
                        equalThreshold: null,
                    });
                    self.ctx.$scope.alarmConfig.deviceThresholds.push({
                        type: "Movement",
                        status: false,
                        durationThreshold: null
                    });
                    self.ctx.$scope.alarmConfig.deviceThresholds.push({
                        type: "Idle",
                        status: false,
                        durationThreshold: null
                    });
                    self.ctx.$scope.datasource = self.ctx.$scope.alarmConfig.deviceThresholds;
                    self.ctx.$scope.displayedColumns = ["type", "upperThreshold", "lowerThreshold", "equalThreshold", "durationThreshold", "status", "edit"];

                    self.ctx.$scope.displayedColumnsTable = [
                        {key: "type", label: "type", isAction: false}, 
                        {key: "upperThreshold", label: "Upper Threshold", isAction: false}, 
                        {key: "lowerThreshold", label: "Lower Threshold", isAction: false}, 
                        {key: "equalThreshold", label: "Equal Threshold", isAction: false}, 
                        {key: "durationThreshold", label: "DurationThreshold", isAction: false}, 
                        {key: "status", label: "Status", isAction: false}, 
                        {key: "edit", label: "Edit", isAction: true, actionKey: "edit"},
                    ];
                }
            } else {
                if(self.ctx.$scope.alarmConfig.locationThresholds && self.ctx.$scope.alarmConfig.locationThresholds.length){
                    self.ctx.$scope.datasource = self.ctx.$scope.alarmConfig.locationThresholds;
                    self.ctx.$scope.displayedColumnsTable = [
                        {key: "eventType", label: "Event Type", isAction: false}, 
                        {key: "duration", label: "Duration", isAction: false}, 
                        {key: "edit", label: "Edit", isAction: true, actionKey: "edit"},
                        {key: "delete_outline", label: "Delete", isAction: true, actionKey: "delete_outline"}
                    ];
                    self.ctx.$scope.displayedColumns = ["eventType", "duration", "edit", "delete_outline"];
                } else {
                    self.ctx.$scope.noData = true;
                }
            }
        }
    }
};

self.actionSources = function() {
    return {
        'elementClick': {
            name: 'widget-action.element-click',
            multiple: true
        }
    };
};

self.onResize = function() {

};

self.onDestroy = function() {
};

